import React from "react";

const MusicForm = ({ value, onChange, onKeyDown, onKeyUp }) => {
  return (
    <div className="form">
      <input
        value={value} //여기에 작성한 value(url)이 함수로 전달되어야 함
        placeholder="플레이리스트에 추가할 유튜브 링크를 입력해 주세요..."
        onChange={onChange}
      />
      <button
        className="create-button"
        onKeyDown={onKeyDown} //자바함수가 실행되어야함}
        onKeyUp={onKeyUp} //인풋에 작성한 내용 다 지워져야함
      >
        추가
      </button>
    </div>
  );
};

export default MusicForm;
